function [lat, lon, h] = geodetic(r)
%GEODETIC  Geodetic latitude, longitude and height on WGS-84 of an Earth-fixed position (three fixed-point
%   passes from Bowring's start).
%   r: real[m][3] (passed in m)
%   returns lat: real[1] (passed a plain number)
%   returns lon: real[1] (passed a plain number)
%   returns h: real[m] (passed in m)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    lat = 0;
    lon = 0;
    h = 0;
    a = 6378137;
    f = (1 / 298.257223563);
    e2 = (f * (2 - f));
    p = sqrt(((r(1) * r(1)) + (r(2) * r(2))));
    lon = atan2(r(2), r(1));
    la = atan2(r(3), (p * (1 - e2)));
    nn = a;
    hh = 0;
    for k = (0):((3) - 1)
        sl = sin(la);
        nn = (a / sqrt((1 - ((e2 * sl) * sl))));
        hh = ((p / cos(la)) - nn);
        la = atan2(r(3), (p * (1 - ((e2 * nn) / (nn + hh)))));
    end
    lat = la;
    h = hh;
end
